/**
 * The tray icon, embedded so the built app needs no file next to it. The PNGs are generated by tools/make_icons.ts from
 * outputs/agent-studio/icons/src/ into tray_icon_data.ts.
 *
 * Windows: a one-colour glyph that matches the taskbar: white (tray-dark.svg) on a dark taskbar, ink (tray-light.svg) on a light one
 * (HKCU\...\Themes\Personalize SystemUsesLightTheme; unknown counts as dark, Windows' default). 16 px when the system's small icon
 * is 16 px (100% scaling), else 32 px, which Windows scales down to 20/24 px.
 * macOS and Linux: the full-colour small app icon at 32 px (Deno.Tray has no template-image option; the panel scales it).
 */
import { advapi32, user32, wide } from '../platform/win32.ts';
import { TRAY_PNG_BASE64 } from './tray_icon_data.ts';

export type TrayArt = 'dark' | 'light' | 'color';
export interface TrayChoice {
  art: TrayArt;
  size: 16 | 32;
}

/**
 * Which tray image to use. lightTaskbar: Windows' SystemUsesLightTheme (null when it could not be read); smallIconPx: the system's
 * small icon size (GetSystemMetrics SM_CXSMICON, 0 when unknown).
 */
export function chooseTrayIcon(os: typeof Deno.build.os, lightTaskbar: boolean | null, smallIconPx: number): TrayChoice {
  if (os !== 'windows') return { art: 'color', size: 32 };
  return { art: lightTaskbar === true ? 'light' : 'dark', size: smallIconPx > 0 && smallIconPx <= 16 ? 16 : 32 };
}

/** The PNG for a choice. */
export function trayIconBytes(choice: TrayChoice): Uint8Array {
  const b64 = TRAY_PNG_BASE64[`${choice.art}-${choice.size}`] ?? TRAY_PNG_BASE64['color-32'];
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

const HKEY_CURRENT_USER = 0xFFFFFFFF80000001n; // (HKEY)(LONG)0x80000001, sign-extended on 64-bit Windows
const RRF_RT_REG_DWORD = 0x10;

/** Windows: does the taskbar use the light theme? null when unknown (the value is missing on old builds, or not Windows). */
export function windowsTaskbarIsLight(): boolean | null {
  if (Deno.build.os !== 'windows') return null;
  try {
    const data = new Uint32Array(1), size = new Uint32Array([4]);
    const status = advapi32().RegGetValueW(
      Deno.UnsafePointer.create(HKEY_CURRENT_USER),
      wide('Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize'),
      wide('SystemUsesLightTheme'),
      RRF_RT_REG_DWORD,
      null,
      data,
      size,
    );
    return status === 0 ? data[0] !== 0 : null;
  } catch {
    return null;
  }
}

/** Windows: the small icon width in pixels (SM_CXSMICON), as the tray will draw it; 0 when unknown. */
export function windowsSmallIconPx(): number {
  if (Deno.build.os !== 'windows') return 0;
  try {
    return user32().GetSystemMetrics(49); // SM_CXSMICON
  } catch {
    return 0;
  }
}

/** The tray PNG for this machine, read now (the taskbar theme and scaling at start-up). */
export function trayIconPng(): Uint8Array {
  return trayIconBytes(chooseTrayIcon(Deno.build.os, windowsTaskbarIsLight(), windowsSmallIconPx()));
}
